CREATE TABLE IF NOT EXISTS `dpn_medical_diseases` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`disease_id` varchar(64) NOT NULL,`severity` int NOT NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),`updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),PRIMARY KEY (`id`),UNIQUE KEY `uq_disease` (`patient_cid`,`disease_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
